function applyStateVisualNudge(d, lon, lat) {
  // targeted visual nudges for edge/coastal coordinates so pins sit inside state borders
  if (d.state_abbr === "NC") {
    lat += 0.6;
  }
  if (d.state_abbr === "CA") {
    lon += 0.7;

    // Stronger upward shift for SoCal (fine-tuned)
    if (lat < 35) {
      lat += 0.55;
    } else {
      lat -= 0.05;
    }
  }
  if (d.state_abbr === "LA") {
    lon += 0.45;
    lat -= 0.05;
  }

  if (d.state_abbr === "KS") {
    lon -= 0.25;  // move Kansas pin slightly left
  }

  if (d.state_abbr === "AL") {
    lat += 0.25;  // move Alabama pin slightly higher
  }

  if (d.state_abbr === "FL") {
    lon += 0.4;   // slightly less right (moves a bit left)
    lat += 0.3;
  }
  if (d.state_abbr === "FL") {
    lon += 0.18;
    lat += 0.08;
  }
  if (d.state_abbr === "HI") {
    lon -= 0.25;  // move slightly left
    lat += 0.6;   // keep upward shift
  }
  return [lon, lat];
}

function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(a) {
  return function() {
    let t = a += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}

