function setView(view) {
  activeView = view;
  const isInPerson = view === "inperson";
  const isVirtual = view === "virtual";
  const isAll = view === "all";

  const inpersonControls = document.getElementById("controls");
  const inpersonMetaRow = document.getElementById("inpersonMetaRow");

  chartView.classList.toggle("is-hidden", !isInPerson);
  virtualView.classList.toggle("is-hidden", !isVirtual);
  allView.classList.toggle("is-hidden", !isAll);

  inpersonControls.classList.remove("is-hidden");
  inpersonMetaRow.classList.toggle("is-hidden", !isInPerson);

  const allControls = document.querySelector(".all-controls");
  const virtualControls = document.querySelector(".virtual-controls");
  if (allControls) allControls.classList.add("is-hidden");
  if (virtualControls) virtualControls.classList.add("is-hidden");

  document.querySelectorAll("#viewToggle .view-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.view === view);
  });

  lockedEventId = null;
  lockedPinNode = null;

  if (typeof pinSelection !== "undefined" && pinSelection) {
    pinSelection.classed("is-active", false)
      .interrupt()
      .transition()
      .duration(140)
      .attr("transform", d => `translate(${d.x},${d.y}) scale(1)`);
  }

  if (typeof virtualPinSelection !== "undefined" && virtualPinSelection) {
    virtualPinSelection.classed("is-active", false)
      .interrupt()
      .transition()
      .duration(140)
      .attr("transform", d => `translate(${d.x},${d.y}) scale(1)`);
  }

  if (typeof allPinSelection !== "undefined" && allPinSelection) {
    allPinSelection.classed("is-active", false)
      .interrupt()
      .transition()
      .duration(140)
      .attr("transform", d => `translate(${d.x},${d.y}) scale(1)`);
  }

  if (isInPerson) {
    renderInpersonTableFiltered(selectedMonth);
  }

  if (isVirtual) {
    renderVirtualTableFiltered();
    if (typeof updateVirtualMap === "function") updateVirtualMap();
  }

  if (isAll) {
    renderAllTableFiltered();
    if (typeof updateAllMap === "function") updateAllMap();
  }

  hideTooltip(true);
}

document.getElementById("viewToggle").querySelectorAll(".view-btn").forEach(btn => {
  btn.addEventListener("click", () => setView(btn.dataset.view));
});


const searchSuggestions = document.getElementById("searchSuggestions");
const eventSearchSuggestions = document.getElementById("eventSearchSuggestions");

function getUniqueSpeakers() {
  const names = [...new Set([...events, ...virtualEvents].map(d => d.speaker).filter(Boolean))];
  return names.sort((a, b) => a.localeCompare(b));
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function highlightMatch(text, query) {
  if (!query) return text;
  const pattern = new RegExp(`(${escapeRegExp(query)})`, "ig");
  return text.replace(pattern, "<mark>$1</mark>");
}

const speakerList = getUniqueSpeakers();

function getUniqueEvents() {
  const names = [...new Set([...events, ...virtualEvents].map(d => d.event_name).filter(Boolean))];
  return names.sort((a, b) => a.localeCompare(b));
}

const eventList = getUniqueEvents();

function renderEventSuggestions(query = "") {
  const normalized = query.trim().toLowerCase();
  const matches = eventList
    .filter(name => !normalized || name.toLowerCase().includes(normalized));

  if (!matches.length) {
    eventSearchSuggestions.classList.add("is-hidden");
    eventSearchSuggestions.innerHTML = "";
    return;
  }

  const header = normalized ? "Suggested events" : "Browse events";
  eventSearchSuggestions.innerHTML = `
    <div class="suggestion-header">${header}</div>
    ${matches.map(name => `<div class="suggestion-item">${highlightMatch(name, normalized)}</div>`).join("")}
  `;
  eventSearchSuggestions.classList.remove("is-hidden");

  [...eventSearchSuggestions.querySelectorAll(".suggestion-item")].forEach(el => {
    el.onclick = () => {
      eventSearch.value = el.textContent;
      eventSearchSuggestions.classList.add("is-hidden");
      eventSearch.dispatchEvent(new Event("input"));
    };
  });
}

function renderSpeakerSuggestions(query = "") {
  const normalized = query.trim().toLowerCase();
  const matches = speakerList
    .filter(name => !normalized || name.toLowerCase().includes(normalized));

  if (!matches.length) {
    searchSuggestions.classList.add("is-hidden");
    eventSearchSuggestions.classList.add("is-hidden");
    searchSuggestions.innerHTML = "";
    return;
  }

  const header = normalized ? "Suggested speakers" : "Browse speakers";
  searchSuggestions.innerHTML = `
    <div class="suggestion-header">${header}</div>
    ${matches.map(name => `<div class="suggestion-item">${highlightMatch(name, normalized)}</div>`).join("")}
  `;
  searchSuggestions.classList.remove("is-hidden");

  [...searchSuggestions.querySelectorAll(".suggestion-item")].forEach(el => {
    el.onclick = () => {
      speakerSearch.value = el.textContent;
      searchSuggestions.classList.add("is-hidden");
      speakerSearch.dispatchEvent(new Event("input"));
    };
  });
}

